INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nature', 'n.', '/ˈneɪtʃə(r)/', '自然;大自然;本质', 'Scientists are always trying to reveal the secrets of nature.', '科学家们一直在努力揭示自然的奥秘。', 'Revealing Nature', 1, 0, 'senior', 'wordlist', 'elective1', 'U5', 'the secrets of nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'species', 'n.', '/ˈspiːʃiːz/', '物种;种类', 'Each year scientists identify many new species of plants and animals.', '每年科学家都会鉴定出许多动植物新物种。', 'Revealing Nature', 2, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a new species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'evolve', 'v.', '/ɪˈvɒlv/', '进化;逐渐发展', 'Darwin believed that birds evolve as they adapt to their environment.', '达尔文认为鸟类随着适应环境而进化。', 'Revealing Nature', 3, 0, 'senior', 'wordlist', 'elective1', 'U5', 'evolve from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'evolution', 'n.', '/ˌiːvəˈluːʃ(ə)n/', '进化;进化论;演变', 'The theory of evolution changed how people understand nature.', '进化论改变了人们对自然的理解。', 'Revealing Nature', 4, 0, 'senior', 'wordlist', 'elective1', 'U5', 'the theory of evolution', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ancestor', 'n.', '/ˈænsestə(r)/', '(动物的)原种;祖先;先辈', 'The finches had evolved from a common ancestor.', '这些雀鸟是从一个共同的原种进化而来的。', 'Revealing Nature', 5, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a common ancestor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suspect', 'v.', '/səˈspekt/', '猜想;怀疑;觉得', 'Darwin began to suspect that species could change over time.', '达尔文开始猜想物种会随时间而改变。', 'Revealing Nature', 6, 0, 'senior', 'wordlist', 'elective1', 'U5', 'suspect that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'detect', 'v.', '/dɪˈtekt/', '发现;察觉;探测', 'A bean plant can detect the chemicals released by an injured neighbour.', '豆类植物能察觉到受伤邻株释放的化学物质。', 'Revealing Nature', 7, 0, 'senior', 'wordlist', 'elective1', 'U5', 'detect the chemicals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'generate', 'v.', '/ˈdʒenəreɪt/', '产生;创造;引起', 'His journey on the Beagle helped him generate a completely new idea.', '他在贝格尔号上的航行帮助他产生了一个全新的想法。', 'Revealing Nature', 8, 0, 'senior', 'wordlist', 'elective1', 'U5', 'generate new ideas', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'characteristic', 'n.', '/ˌkærəktəˈrɪstɪk/', '特征;特性;特点', 'Each species has developed its own physical characteristics.', '每个物种都发展出了自己独特的身体特征。', 'Revealing Nature', 9, 0, 'senior', 'wordlist', 'elective1', 'U5', 'physical characteristics', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'adapt', 'v.', '/əˈdæpt/', '适应;改编;调整', 'Animals slowly adapt to a changing environment in order to survive.', '动物为了生存会慢慢适应不断变化的环境。', 'Revealing Nature', 10, 0, 'senior', 'wordlist', 'elective1', 'U5', 'adapt to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'environment', 'n.', '/ɪnˈvaɪrənmənt/', '环境;自然环境', 'Darwin studied living things in their natural environment.', '达尔文在自然环境中研究各种生物。', 'Revealing Nature', 11, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a natural environment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sample', 'n.', '/ˈsɑːmp(ə)l/', '样本;标本;样品', 'His cabin was crowded with samples of plants and animals.', '他的船舱里堆满了动植物标本。', 'Revealing Nature', 12, 0, 'senior', 'wordlist', 'elective1', 'U5', 'collect samples', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'geologist', 'n.', '/dʒiˈɒlədʒɪst/', '地质学家', 'As a geologist, Darwin was fascinated by rocks and the land.', '作为地质学家,达尔文对岩石和土地着迷。', 'Revealing Nature', 13, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a young geologist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'naturalist', 'n.', '/ˈnætʃ(ə)rəlɪst/', '博物学家;自然主义者', 'Darwin''s curiosity about living things made him a great naturalist.', '达尔文对生物的好奇使他成为伟大的博物学家。', 'Revealing Nature', 14, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a great naturalist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'discovery', 'n.', '/dɪˈskʌv(ə)ri/', '发现;发觉', 'His adventures led to one of the most important scientific discoveries of all time.', '他的探险带来了有史以来最重要的科学发现之一。', 'Revealing Nature', 15, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a scientific discovery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scientific', 'adj.', '/ˌsaɪənˈtɪfɪk/', '科学的;科学上的', 'Darwin''s scientific studies were so convincing that people began to believe him.', '达尔文的科学研究极有说服力,人们开始相信他。', 'Revealing Nature', 16, 0, 'senior', 'wordlist', 'elective1', 'U5', 'scientific studies', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'primitive', 'adj.', '/ˈprɪmətɪv/', '原始的;低等的;早期的', 'All the iguanas have developed from more primitive ones.', '所有鬣蜥都是从更原始的种类发展而来的。', 'Revealing Nature', 17, 0, 'senior', 'wordlist', 'elective1', 'U5', 'primitive forms of life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'habitat', 'n.', '/ˈhæbɪtæt/', '栖息地;生境', 'Mangroves serve as the habitat for various birds and fish.', '红树林是各种鸟类和鱼类的栖息地。', 'Revealing Nature', 18, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a natural habitat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ecosystem', 'n.', '/ˈiːkəʊsɪstəm/', '生态系统', 'Coastal plants are very important to the local ecosystem.', '海岸植物对当地生态系统非常重要。', 'Revealing Nature', 19, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a fragile ecosystem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'appearance', 'n.', '/əˈpɪərəns/', '外貌;外观;出现', 'Iguanas have a very special appearance, with spines on their back.', '鬣蜥外貌很特别,背上长着刺。', 'Revealing Nature', 20, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a special appearance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'decline', 'v.', '/dɪˈklaɪn/', '(数量)下降;减少;衰退;婉拒', 'After goats were brought in, the tortoise population began to decline.', '山羊被引入后,陆龟数量开始减少。', 'Revealing Nature', 21, 0, 'senior', 'wordlist', 'elective1', 'U5', 'decline sharply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'blame', 'v.', '/bleɪm/', '责怪;指责;把……归咎于', 'The extinction of the tortoise is blamed on humans.', '这种陆龟的灭绝被归咎于人类。', 'Revealing Nature', 22, 0, 'senior', 'wordlist', 'elective1', 'U5', 'be blamed on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'link', 'v.', '/lɪŋk/', '连接;把……联系起来', 'This fungal network can link nearly every plant in a forest.', '这个真菌网络几乎能把森林里的每株植物连接起来。', 'Revealing Nature', 23, 0, 'senior', 'wordlist', 'elective1', 'U5', 'link to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'root', 'n.', '/ruːt/', '根;根部;根源', 'The wood wide web links the roots of different plants to each other.', '“木维网”把不同植物的根彼此连接起来。', 'Revealing Nature', 24, 0, 'senior', 'wordlist', 'elective1', 'U5', 'the roots of plants', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'seed', 'n.', '/siːd/', '种子;籽', 'She watched the seed slowly grow into a tall green plant.', '她看着种子慢慢长成一株高高的绿色植物。', 'Revealing Nature', 25, 0, 'senior', 'wordlist', 'elective1', 'U5', 'plant a seed', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distant', 'adj.', '/ˈdɪstənt/', '遥远的;久远的', 'The captain wanted someone who would profit from visiting distant countries.', '船长想找一个能从游历遥远国度中获益的人。', 'Revealing Nature', 26, 0, 'senior', 'wordlist', 'elective1', 'U5', 'distant countries', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disgrace', 'n.', '/dɪsˈɡreɪs/', '丢脸;耻辱', 'His father once predicted that he would be a disgrace to the family.', '他父亲曾预言他会成为家族的耻辱。', 'Revealing Nature', 27, 0, 'senior', 'wordlist', 'elective1', 'U5', 'be a disgrace', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'finch', 'n.', '/fɪntʃ/', '雀科鸣禽;雀', 'The finches on each island had different beaks.', '每座岛上的雀鸟都长着不同的喙。', 'Revealing Nature', 28, 0, 'senior', 'wordlist', 'elective1', 'U5', 'the finches on the islands', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'beak', 'n.', '/biːk/', '鸟嘴;喙', 'Their beaks had evolved according to the food available on each island.', '它们的喙随各岛可获取的食物而进化。', 'Revealing Nature', 29, 0, 'senior', 'wordlist', 'elective1', 'U5', 'the bird''s beak', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tortoise', 'n.', '/ˈtɔːtəs/', '陆龟', 'Lonesome George was the last Pinta Island tortoise.', '“孤独的乔治”是最后一只平塔岛陆龟。', 'Revealing Nature', 30, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a giant tortoise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'goat', 'n.', '/ɡəʊt/', '山羊', 'After goats were brought to the island, the tortoises lost their food.', '山羊被带到岛上后,陆龟失去了食物。', 'Revealing Nature', 31, 0, 'senior', 'wordlist', 'elective1', 'U5', 'bring goats to the island', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mangrove', 'n.', '/ˈmæŋɡrəʊv/', '红树(林)', 'Mangroves are coastal plants that grow in or near water.', '红树是生长在水中或水边的海岸植物。', 'Revealing Nature', 32, 0, 'senior', 'wordlist', 'elective1', 'U5', 'coastal mangroves', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spine', 'n.', '/spaɪn/', '(动植物的)刺;脊柱', 'Iguanas have comb-like spines along their back.', '鬣蜥背上长着梳子状的刺。', 'Revealing Nature', 33, 0, 'senior', 'wordlist', 'elective1', 'U5', 'comb-like spines', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'myth', 'n.', '/mɪθ/', '神话;虚构的故事', 'Talking plants have long been a thing of myths and legends.', '会说话的植物长久以来都是神话传说中的事物。', 'Revealing Nature', 34, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a thing of myths', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'legend', 'n.', '/ˈledʒ(ə)nd/', '传说;传奇(故事)', 'Many cultures have legends of talking trees that give advice.', '许多文化中都有会给人建议的会说话的树的传说。', 'Revealing Nature', 35, 0, 'senior', 'wordlist', 'elective1', 'U5', 'stories and legends', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wasp', 'n.', '/wɒsp/', '黄蜂', 'Some chemicals attract wasps that kill the harmful insects.', '有些化学物质会吸引黄蜂来杀死有害昆虫。', 'Revealing Nature', 36, 0, 'senior', 'wordlist', 'elective1', 'U5', 'attract wasps', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pesticide', 'n.', '/ˈpestɪsaɪd/', '杀虫剂;农药', 'Scientists hope we can grow crops without using pesticides.', '科学家希望我们能不用杀虫剂就种出庄稼。', 'Revealing Nature', 37, 0, 'senior', 'wordlist', 'elective1', 'U5', 'grow crops without pesticides', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'chilli', 'n.', '/ˈtʃɪli/', '辣椒', 'A chilli plant can tell if a neighbouring plant is friendly.', '辣椒植株能分辨邻近的植物是否友好。', 'Revealing Nature', 38, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a chilli plant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fungus', 'n.', '/ˈfʌŋɡəs/', '真菌(复数 fungi)', 'The wood wide web is linked underground by fungi, a kind of fungus.', '“木维网”由地下的真菌连接而成。', 'Revealing Nature', 39, 0, 'senior', 'wordlist', 'elective1', 'U5', 'underground fungi', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cybercrime', 'n.', '/ˈsaɪbəkraɪm/', '网络犯罪', 'The wood wide web has its own version of cybercrime.', '“木维网”也有自己版本的网络犯罪。', 'Revealing Nature', 40, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a version of cybercrime', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'centimetre', 'n.', '/ˈsentɪmiːtə(r)/', '厘米', 'Each stem had grown to around twenty centimetres tall.', '每根茎都长到了约二十厘米高。', 'Revealing Nature', 41, 0, 'senior', 'wordlist', 'elective1', 'U5', 'twenty centimetres tall', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'worldwide', 'adv.', '/ˌwɜːldˈwaɪd/', '遍及全世界;在全世界', 'The Galápagos Islands are renowned worldwide for their biodiversity.', '加拉帕戈斯群岛因其生物多样性而闻名全世界。', 'Revealing Nature', 42, 0, 'senior', 'wordlist', 'elective1', 'U5', 'renowned worldwide', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'giant', 'adj.', '/ˈdʒaɪənt/', '巨大的;特大的', 'The reserve is home to several species of giant tortoise.', '这个保护区是好几种巨型陆龟的家园。', 'Revealing Nature', 43, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a giant tortoise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'iguana', 'n.', '/ɪˈɡwɑːnə/', '鬣蜥', 'Iguanas can be found on several of the islands.', '在好几座岛上都能发现鬣蜥。', 'Revealing Nature', 44, 0, 'senior', 'wordlist', 'elective1', 'U5', 'marine iguanas', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'answer the call', 'phr.', '/ˈɑːnsə ðə kɔːl/', '响应号召', 'The young man who answered the call was not the captain''s first choice.', '响应号召的那个年轻人并不是船长的首选。', 'Revealing Nature', 45, 0, 'senior', 'wordlist', 'elective1', 'U5', 'answer the call', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'be native to', 'phr.', '/biː ˈneɪtɪv tə/', '原产于;源于(某地)', 'Several species of tortoise are native to the Galápagos Islands.', '好几种陆龟原产于加拉帕戈斯群岛。', 'Revealing Nature', 46, 0, 'senior', 'wordlist', 'elective1', 'U5', 'be native to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'be home to', 'phr.', '/biː həʊm tə/', '是……的栖息地;拥有', 'The island is home to many rare plants and animals.', '这座岛是许多珍稀动植物的家园。', 'Revealing Nature', 47, 0, 'senior', 'wordlist', 'elective1', 'U5', 'be home to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fungal', 'adj.', '/ˈfʌŋɡ(ə)l/', '真菌的', 'This fungal network links the roots of different plants.', '这个真菌网络把不同植物的根连接起来。', 'Revealing Nature', 48, 0, 'senior', 'wordlist', 'elective1', 'U5', 'a fungal network', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u5.01', '①had done:在某个过去时间点之前 / 在另一个过去动作之前已完成', 'A2', 11, '外研社版选择性必修第一册 U5 — 句中有 by/before/when/by the time 等过去参照点,某动作在该参照点之前已经发生、完成,用过去完成时 had done;主句或参照为一般过去时。', 1, 'elective1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u5.02', '②过去完成时 vs 一般过去时:先发生的动作用 had done', 'A2', 11, '外研社版选择性必修第一册 U5 — 一句话里有两个过去动作,先发生的(更早的)用过去完成时 had done,后发生的用一般过去时;通过先后顺序判断哪一个用过去完成时。', 2, 'elective1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u5.03', '③间接引语中的过去完成时 & no sooner…than / hardly…when 倒装', 'A2', 11, '外研社版选择性必修第一册 U5 — 间接引语里,比''说''更早发生的过去动作要回退为过去完成时;no sooner…than、hardly…when 句首倒装时,助动词用 had(had + 主语 + 过去分词)。', 3, 'elective1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By the time the Beagle reached the islands, Darwin ____ many samples of plants and animals.', 'had collected', 'collected', 'has collected', 'collects', 'A', 'by the time + 过去,采集动作在到达之前就已完成 → 过去完成时 had collected。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Before he left England, Darwin ____ medical school without finishing his degree.', 'left', 'had left', 'has left', 'leaves', 'B', 'before 引出的过去参照点之前已发生的动作用过去完成时 had left。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'When the storm finally stopped, the ship ____ already sailed far from the coast.', 'has', 'was', 'had', 'did', 'C', 'already sailed 表示在 stopped 之前就完成,助动词用 had。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By 1835, the birds ____ into several clearly different species.', 'evolved', 'have evolved', 'evolve', 'had evolved', 'D', 'by + 过去年份,之前已完成的进化用过去完成时 had evolved。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Darwin realised that the finches ____ from a common ancestor long before.', 'had come', 'came', 'have come', 'come', 'A', 'long before 表示比 realised 更早,用过去完成时 had come。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Before the goats arrived, the tortoises ____ the plants that grew naturally there.', 'ate', 'had eaten', 'have eaten', 'eat', 'B', 'before 过去参照点之前的动作用过去完成时 had eaten。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By the end of the voyage, his small cabin ____ full of samples.', 'became', 'has become', 'had become', 'becomes', 'C', 'by the end of + 过去,之前已完成的变化用过去完成时 had become。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'When she checked the pot, a tiny green stem ____ already appeared.', 'has', 'was', 'did', 'had', 'D', 'already appeared 表示在 checked 之前已出现,助动词用 had。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Darwin noticed that some species ____ very little since ancient times.', 'had changed', 'changed', 'have changed', 'change', 'A', 'noticed 为过去,从句中更早的情况用过去完成时 had changed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By the time scientists studied the water bear, it ____ already survived extreme cold.', 'has', 'had', 'was', 'did', 'B', 'by the time + 过去,already survived 之前已完成,助动词用 had。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Before Mendel died in 1884, he ____ important discoveries about genetics.', 'made', 'has made', 'had made', 'makes', 'C', 'before + 过去时间,之前完成的动作用过去完成时 had made。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'When the wasps arrived, the bean plant ____ already released its warning chemicals.', 'has', 'did', 'was', 'had', 'D', 'already released 表示在 arrived 之前完成,助动词用 had。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Darwin saw species on the islands that ____ never been recorded before.', 'had', 'has', 'were', 'did', 'A', 'never been recorded before 表示在 saw 之前的情况,用过去完成时,助动词 had。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Before the journal entry was written, each bulb ____ produced a single flower.', 'has', 'had', 'was', 'did', 'B', 'before + 过去,之前已完成的动作用过去完成时,助动词 had。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By the time the keeper arrived, George ____ already become famous worldwide.', 'has', 'was', 'had', 'did', 'C', 'by the time + 过去,already become 之前完成,助动词用 had。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'After the seeds ____ been planted, water was added to the soil.', 'has', 'were', 'did', 'had', 'D', 'after 引出更早的动作,被动的过去完成时用 had been planted,助动词 had。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Darwin explained that the beaks ____ to match the food on each island.', 'had adapted', 'adapted', 'have adapted', 'adapt', 'A', 'explained 为过去,从句中更早的进化用过去完成时 had adapted。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'By 1859, Darwin ____ his whole theory in a famous book.', 'explained', 'had explained', 'has explained', 'explains', 'B', 'by + 过去年份,之前已完成的动作用过去完成时 had explained。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'When the researchers reached the forest, the fungi ____ already linked the trees underground.', 'has', 'were', 'had', 'did', 'C', 'already linked 表示在 reached 之前完成,助动词用 had。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.01'), 'Before the book was published, many people ____ never questioned the old ideas about species.', 'has', 'were', 'did', 'had', 'D', 'never questioned before 表示在 published 之前的情况,用过去完成时,助动词 had。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'After Darwin ____ some time in South America, he sailed on to the Galápagos.', 'had spent', 'spent', 'has spent', 'spends', 'A', '两个过去动作中,逗留先发生,用过去完成时 had spent;后面 sailed 用一般过去时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The finches had evolved from an ancestor that ____ on the islands long before.', 'arrived', 'had arrived', 'has arrived', 'arrives', 'B', '到达比进化更早,先发生的动作用过去完成时 had arrived。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Once the insects ____ the leaves, the plant began to release chemicals.', 'attacked', 'have attacked', 'had attacked', 'attack', 'C', '攻击先发生、随后才释放化学物质,先发生的用过去完成时 had attacked。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Darwin carefully studied the samples that he ____ during the long voyage.', 'collected', 'has collected', 'collects', 'had collected', 'D', '采集在研究之前,先发生的动作用过去完成时 had collected。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The tortoise population fell sharply because goats ____ almost all its food.', 'had eaten', 'ate', 'have eaten', 'eat', 'A', '山羊吃光食物在数量下降之前,先发生的用过去完成时 had eaten。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'People were shocked because they ____ always believed that species never changed.', 'have', 'had', 'were', 'did', 'B', '震惊之前一直持有的旧观念用过去完成时 had always believed,助动词 had。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'When the wasps came, the harmful insects ____ already damaged much of the crop.', 'have', 'were', 'had', 'did', 'C', '破坏庄稼在黄蜂到来之前完成,先发生的用过去完成时,助动词 had。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Mendel chose pea plants because earlier work ____ him their traits were easy to control.', 'taught', 'have taught', 'teach', 'had taught', 'D', '先前的研究在他选择之前已让他明白,用过去完成时 had taught。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'By the time George was found, all the other Pinta tortoises ____ already died.', 'had', 'have', 'were', 'did', 'A', '其他陆龟死亡在乔治被发现之前,先发生的用过去完成时,助动词 had。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The young plant grew tall and strong because someone ____ it carefully every day.', 'watered', 'had watered', 'has watered', 'waters', 'B', '之前每天浇水促成了后来的生长,先发生的用过去完成时 had watered。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Darwin often asked himself how the different species ____ come to exist at all.', 'have', 'were', 'had', 'did', 'C', '物种出现远早于他发问,先发生的用过去完成时,助动词 had。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'She drew the flower exactly as it ____ looked the week before.', 'has', 'was', 'did', 'had', 'D', 'the week before 表示画之前的样子,用过去完成时,助动词 had。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The forest recovered quickly because the fungi ____ the trees together underground.', 'had linked', 'linked', 'have linked', 'link', 'A', '真菌连接在森林恢复之前已完成,先发生的用过去完成时 had linked。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'After the bulbs ____ been planted, the container was put in a dark place.', 'have', 'had', 'were', 'did', 'B', '种球先被种下、后放进暗处,先发生的被动动作用过去完成时,助动词 had。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The chilli plant reacted at once because it ____ a warning from its neighbour.', 'detected', 'has detected', 'had detected', 'detects', 'C', '察觉警告在反应之前,先发生的用过去完成时 had detected。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Many readers refused to accept the idea, although Darwin ____ explained it very clearly.', 'has', 'was', 'did', 'had', 'D', '达尔文解释在读者拒绝之前已完成,先发生的用过去完成时,助动词 had。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'By the time the ship returned home, Darwin ____ enough evidence for his theory.', 'had gathered', 'gathered', 'has gathered', 'gathers', 'A', '搜集证据在返航之前完成,先发生的用过去完成时 had gathered。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The keeper said the tortoise looked much weaker than it ____ the year before.', 'has', 'had', 'was', 'did', 'B', 'the year before 指更早的状态,用过去完成时,助动词 had。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'The new species appeared only after older forms slowly ____ over millions of years.', 'changed', 'have changed', 'had changed', 'change', 'C', '旧形态的变化在新物种出现之前,先发生的用过去完成时 had changed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.02'), 'Scientists named the strange creature only after they ____ it in the wild.', 'found', 'have found', 'finds', 'had found', 'D', '发现在命名之前,先发生的用过去完成时 had found。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Darwin said that he ____ the finches carefully before he understood their meaning.', 'had studied', 'studied', 'has studied', 'studies', 'A', '间接引语里比''说''更早的动作回退为过去完成时 had studied。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'The keeper explained that George ____ the last of his kind for many years.', 'was', 'had been', 'has been', 'is', 'B', 'explained 为过去,更早且延续的情况回退为过去完成时 had been。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Scientists reported that the species ____ from a single common ancestor.', 'evolved', 'has evolved', 'had evolved', 'evolve', 'C', '间接引语里更早完成的进化回退为过去完成时 had evolved。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Darwin wrote that the birds'' beaks ____ to suit the food on each island.', 'adapted', 'have adapted', 'adapt', 'had adapted', 'D', 'wrote 为过去,更早的动作回退为过去完成时 had adapted。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'She told us that the seeds ____ already sprouted by the third week.', 'had', 'have', 'were', 'did', 'A', 'told 为过去,already sprouted 更早完成,回退为过去完成时,助动词 had。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'He realised that the goats ____ destroyed the tortoise''s main food supply.', 'have', 'had', 'were', 'did', 'B', 'realised 之前山羊已破坏食物,回退为过去完成时,助动词 had。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'The guide said that plants ____ each other through chemicals long before scientists noticed.', 'warned', 'have warned', 'had warned', 'warn', 'C', 'long before 表更早,间接引语回退为过去完成时 had warned。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Darwin admitted that he ____ medical school without ever finishing his degree.', 'left', 'has left', 'leaves', 'had left', 'D', 'admitted 之前发生的离校,回退为过去完成时 had left。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'The report stated that the fungi ____ the whole forest together underground.', 'had linked', 'linked', 'have linked', 'link', 'A', 'stated 为过去,更早完成的连接回退为过去完成时 had linked。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Mendel noted that the pea plants ____ him a great deal about genetics.', 'taught', 'had taught', 'have taught', 'teach', 'B', 'noted 之前豌豆实验已给出启示,回退为过去完成时 had taught。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'No sooner ____ the ship reached the islands than Darwin noticed the strange birds.', 'has', 'did', 'had', 'was', 'C', 'No sooner 句首倒装,助动词用 had:No sooner had + 主语 + 过去分词。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Hardly ____ the insects attacked the plant when it began to release chemicals.', 'has', 'did', 'was', 'had', 'D', 'Hardly…when 句首倒装,助动词用 had:Hardly had + 主语 + 过去分词。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'No sooner ____ the goats arrived than the tortoise population started to fall.', 'had', 'has', 'did', 'was', 'A', 'No sooner…than 句首倒装,助动词用 had。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Hardly ____ Darwin opened the box when even more samples fell out.', 'has', 'had', 'did', 'was', 'B', 'Hardly…when 句首倒装,助动词用 had。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'No sooner ____ the seed been planted than the gardener added water to the soil.', 'has', 'did', 'had', 'were', 'C', 'No sooner 句首倒装,被动用 had been planted,助动词 had。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Hardly ____ the team landed on the island when they began collecting plants.', 'has', 'did', 'was', 'had', 'D', 'Hardly…when 句首倒装,助动词用 had。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'No sooner ____ the book been published than it caused a storm of argument.', 'had', 'has', 'did', 'were', 'A', 'No sooner 句首倒装,被动用 had been published,助动词 had。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Hardly ____ the sun risen when the birds started singing across the forest.', 'has', 'had', 'did', 'was', 'B', 'Hardly…when 句首倒装,助动词用 had。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'No sooner ____ scientists found one new species than they discovered another.', 'has', 'did', 'had', 'was', 'C', 'No sooner…than 句首倒装,助动词用 had。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U5' AND code='fe1u5.03'), 'Hardly ____ the chilli plant sensed danger when it changed its behaviour.', 'has', 'did', 'was', 'had', 'D', 'Hardly…when 句首倒装,助动词用 had。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Darwin and the Beagle', 'In 1831, a young man named Charles Darwin boarded a ship called the Beagle and set off to explore distant lands. He was not the captain''s first choice, and his own father had once warned that he might bring shame on the family. Yet Darwin was deeply curious about rocks, plants and animals, and the long voyage gave him a rare chance to study living things in their own surroundings. As the ship moved from place to place, he gathered countless samples until his small cabin was crowded with them. While he examined what he had found, one question kept returning to his mind: why do so many different kinds of creatures exist? That simple question would slowly grow into one of the greatest scientific ideas ever known, and it all started with a single journey across the sea.', '说明·达尔文与贝格尔号航行', 139, '[{"q":"Why was the voyage so valuable for Darwin?","answer":"A","options":["It let him watch creatures where they actually lived.","It made him the captain of the ship.","It helped him finish his medical degree.","It allowed him to stay safely at home."],"explanation":"原文说航行让他在生物''自己的环境中''研究它们,即在野外观察生物。"},{"q":"What had Darwin''s father once feared?","answer":"B","options":["That his son would never travel.","That his son might embarrass the family.","That his son would become a sailor.","That his son would study too hard."],"explanation":"原文 ''might bring shame on the family'' 的转述。"},{"q":"What question kept troubling Darwin during the trip?","answer":"A","options":["Why so many types of living things exist.","How to become a famous captain.","Where to sell his samples.","When the ship would return home."],"explanation":"原文末段他反复自问为何存在这么多不同生物。"}]'::jsonb, '[{"word":"distant","cn":"遥远的"},{"word":"sample","cn":"样本"},{"word":"scientific","cn":"科学的"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Birds That Changed Everything', 'When the Beagle finally reached the Galápagos Islands in 1835, Darwin was amazed by the variety of life he saw there. Of all the creatures, it was the small birds called finches that interested him most. He noticed something strange: the finches on one island did not look quite the same as those on another. In particular, their beaks were different. On islands where the birds fed on hard seeds, the beaks were thick and strong; where softer food was common, the beaks were thin and delicate. Darwin slowly came to a bold conclusion. He believed that all these birds had descended from a single kind of ancestor that had reached the islands long ago. Over many generations, as each group adapted to the food around it, the birds had gradually changed until they became separate species. This idea about change over time lay at the very heart of his later theory.', '说明·加拉帕戈斯雀鸟与喙', 152, '[{"q":"Which creatures interested Darwin the most on the islands?","answer":"B","options":["The giant tortoises.","The small finches.","The blue whales.","The wild goats."],"explanation":"原文 ''it was the small birds called finches that interested him most''。"},{"q":"According to the text, what did a finch''s beak shape depend on?","answer":"C","options":["The colour of its feathers.","The size of the island.","The type of food found on its island.","The number of other birds."],"explanation":"原文硬种子→厚喙、软食物→细喙,取决于食物。"},{"q":"What did Darwin finally conclude about the different finches?","answer":"D","options":["They were brought there by sailors.","They never changed at all.","They could not survive together.","They all came from one shared ancestor."],"explanation":"原文 ''descended from a single kind of ancestor'' 的转述。"}]'::jsonb, '[{"word":"finch","cn":"雀鸟"},{"word":"beak","cn":"喙"},{"word":"ancestor","cn":"原种;祖先"},{"word":"adapt","cn":"适应"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Secret Language of Plants', 'For a long time, people thought that talking plants belonged only to myths and old legends. Modern science, however, has shown that plants really do share information with one another. When insects begin eating a bean plant, the injured leaves give off tiny amounts of chemicals, almost like a cry for help. A nearby plant can detect these chemicals and respond by releasing its own, some of which drive the insects away. Plants also use sound. Certain roots make faint noises that human ears cannot hear, and a chilli plant seems able to sense whether a neighbour is friendly or not. Most surprising of all is a hidden network that connects almost every plant in a forest. Scientists call it the wood wide web, because underground threads of fungi join the roots together. Through this network, plants can pass food and messages, and sometimes one plant even steals from another.', '说明·植物如何交流', 150, '[{"q":"How does an attacked bean plant warn the others?","answer":"A","options":["By giving off chemicals from its leaves.","By making a loud cry that people hear.","By moving closer to its neighbours.","By changing its colour overnight."],"explanation":"原文受伤叶片释放化学物质作为求救信号。"},{"q":"What is the ''wood wide web'' mainly made of?","answer":"B","options":["Thin metal cables under the soil.","Underground fungi joining the roots.","The leaves of large trees.","Tiny insects living in the ground."],"explanation":"原文地下真菌把根连接起来。"},{"q":"Besides chemicals, what else do some plants use to communicate?","answer":"C","options":["Light.","Heat.","Sound.","Colour."],"explanation":"原文 ''Plants also use sound''。"}]'::jsonb, '[{"word":"detect","cn":"察觉"},{"word":"root","cn":"根"},{"word":"fungus","cn":"真菌"},{"word":"link","cn":"连接"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A World Full of Life', 'Our planet is home to millions of different living things, and they come in every imaginable size. Some are so tiny, like bacteria and viruses, that no human eye can see them without help. At the other extreme is the blue whale, the largest animal ever found, which can stretch to nearly thirty metres and weigh more than a hundred thousand kilos. Perhaps the toughest of all is a tiny creature known as the water bear. This remarkable animal can survive burning heat and freezing cold that would quickly kill almost anything else. To live well in its own surroundings, every species has slowly developed features that suit it perfectly. Each year researchers give names to about fifteen thousand species that were unknown before. Even so, scientists believe that millions more are still hidden away, waiting somewhere on Earth to be found and studied for the very first time.', '说明·地球的生物多样性', 149, '[{"q":"Why can''t people see bacteria and viruses with their eyes alone?","answer":"D","options":["They move much too fast.","They hide deep underground.","They only come out at night.","They are far too small."],"explanation":"原文它们太小,肉眼无法看见。"},{"q":"What makes the water bear so remarkable?","answer":"A","options":["It can live through great heat and cold.","It is the largest animal on Earth.","It can fly across the oceans.","It never needs any food."],"explanation":"原文水熊能在极端冷热中存活。"},{"q":"How many new species do researchers name in a typical year?","answer":"B","options":["Only a few hundred.","About fifteen thousand.","Exactly one million.","None at all."],"explanation":"原文每年约命名一万五千个新物种。"}]'::jsonb, '[{"word":"species","cn":"物种"},{"word":"characteristic","cn":"特征"},{"word":"centimetre","cn":"厘米"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Quiet Gardener', 'Long before scientists fully understood how living things pass on their features, a quiet gardener was already finding the answers. Gregor Mendel spent years growing pea plants in a small garden. He chose peas on purpose, because their simple traits, such as flower colour and seed shape, were easy to follow from one generation to the next. Year after year, Mendel carefully crossed his plants and wrote down exactly what happened to the young plants that grew. Patterns slowly appeared in his careful notes. By the time he died in 1884, he had worked out important rules about how features are handed down from parents to offspring. Sadly, very few people paid attention to his work while he was alive. Only many years later did other scientists realise that this patient gardener had quietly laid the foundations of modern genetics, the study of how living things inherit what makes them unique.', '说明·孟德尔与豌豆实验', 151, '[{"q":"Why did Mendel choose pea plants for his work?","answer":"C","options":["They were the only plants he could buy.","They grew faster than any other plant.","Their simple features were easy to track.","They needed almost no water at all."],"explanation":"原文豌豆的简单特征易于追踪。"},{"q":"What did Mendel finally work out?","answer":"D","options":["How to grow the biggest peas.","How to sell plants for money.","How to keep his garden warm.","How living things pass features to their young."],"explanation":"原文他弄清了特征如何由亲代传给后代。"},{"q":"How was Mendel''s work treated while he was alive?","answer":"A","options":["Almost nobody took any notice of it.","Everyone praised it at once.","It was banned by the government.","It made him rich and famous."],"explanation":"原文在世时很少有人关注他的研究。"}]'::jsonb, '[{"word":"seed","cn":"种子"},{"word":"generate","cn":"产生"},{"word":"characteristic","cn":"特征"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Lonesome George', 'On Pinta Island in the Galápagos, one giant tortoise became famous around the world. His name was Lonesome George, and for many years he was the very last of his particular kind. Long before humans came, the Pinta tortoises had lived quietly and safely, feeding on the wild plants that grew across the island. Everything changed when people arrived and brought goats with them. The hungry goats ate the same plants the tortoises depended on, and slowly the tortoise numbers fell. One by one they disappeared, until only George remained. Scientists and keepers did everything they could to care for him and hoped to find him a mate, but none was ever found. When George finally died in 2012, his whole subspecies was declared extinct. His sad story is now a powerful reminder of how easily human actions can wipe out a species that took nature thousands of years to create.', '说明·孤独的乔治与陆龟灭绝', 151, '[{"q":"Who was Lonesome George?","answer":"B","options":["A famous ship captain.","The final tortoise of his kind.","A young naturalist on the island.","The keeper of a zoo."],"explanation":"原文他是其同类中''最后一只''。"},{"q":"What caused the Pinta tortoises to disappear?","answer":"C","options":["A sudden change in the weather.","They were taken to other islands.","Goats ate the plants they needed.","They stopped having young."],"explanation":"原文山羊吃光了陆龟赖以为生的植物。"},{"q":"What does George''s story now remind people of?","answer":"D","options":["Tortoises live longer than any animal.","Islands are safe places for wildlife.","Goats are useful for protecting nature.","Human actions can easily destroy a species."],"explanation":"原文末段提醒人类行为能轻易灭绝一个物种。"}]'::jsonb, '[{"word":"tortoise","cn":"陆龟"},{"word":"goat","cn":"山羊"},{"word":"decline","cn":"减少"},{"word":"blame","cn":"归咎于"}]'::jsonb, 2, 'elective1', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'My Plant Diary', 'Last spring our science teacher gave each of us a single sunflower (1)____ to grow at home. I planted it in a small pot of soft (2)____ and put it on my sunny windowsill. For the first week, nothing seemed to (3)____, and I almost lost hope. Then one morning a tiny green (4)____ pushed its way up through the earth. I was so excited that I (5)____ to water it carefully every day. Slowly the plant grew (6)____ and strong, until it stood taller than my ruler. I used a centimetre ruler to (7)____ its height each week and wrote the numbers in my notebook. By midsummer, a single bright yellow (8)____ had opened at the top. Watching it change taught me how (9)____ nature can be. Now I understand why scientists love to (10)____ living things so closely.', 140, 2, '[{"q":"1","answer":"A","options":["seed","stone","box","song"],"explanation":"a sunflower seed 一颗向日葵种子。"},{"q":"2","answer":"B","options":["glass","soil","paper","metal"],"explanation":"a pot of soil 一盆土。"},{"q":"3","answer":"C","options":["sing","cook","happen","drive"],"explanation":"nothing seemed to happen 似乎什么也没发生。"},{"q":"4","answer":"D","options":["clock","coin","letter","stem"],"explanation":"a tiny green stem 一根嫩绿的茎。"},{"q":"5","answer":"A","options":["decided","refused","forgot","failed"],"explanation":"decided to water it 决定给它浇水。"},{"q":"6","answer":"B","options":["late","tall","cheap","dark"],"explanation":"grew tall and strong 长得又高又壮。"},{"q":"7","answer":"C","options":["throw","sell","measure","hide"],"explanation":"measure its height 测量它的高度。"},{"q":"8","answer":"D","options":["window","wheel","ticket","flower"],"explanation":"a yellow flower 一朵黄花。"},{"q":"9","answer":"A","options":["amazing","boring","ugly","empty"],"explanation":"how amazing nature can be 自然多么神奇。"},{"q":"10","answer":"B","options":["forget","study","leave","break"],"explanation":"study living things 研究生物。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'Naming a New Species', 'Every year, scientists around the world (1)____ thousands of animals and plants that no one has ever described before. Finding a new (2)____ is exciting, but the real work has only just begun. First, the researchers must study the creature''s (3)____, such as its size, colour and shape, very carefully. Then they compare it with its closest (4)____ to make sure it really is new. Giving the creature a proper name can (5)____ a long time, because the name must follow strict scientific rules. Sometimes a species is (6)____ after the place where it was first found; sometimes it honours the person who (7)____ it. Once the name is accepted, it is added to a worldwide (8)____ that all scientists can use. In this way, our knowledge of (9)____ slowly grows. Who knows how many strange creatures are still (10)____ to be discovered?', 143, 2, '[{"q":"1","answer":"C","options":["sell","lose","discover","eat"],"explanation":"discover thousands of animals 发现成千上万的动物。"},{"q":"2","answer":"D","options":["machine","season","price","species"],"explanation":"a new species 一个新物种。"},{"q":"3","answer":"A","options":["features","prices","songs","tickets"],"explanation":"the creature''s features 生物的特征。"},{"q":"4","answer":"B","options":["enemies","relatives","buildings","markets"],"explanation":"its closest relatives 与最近的近亲比较。"},{"q":"5","answer":"C","options":["buy","throw","take","cook"],"explanation":"can take a long time 可能花很长时间。"},{"q":"6","answer":"D","options":["sold","lost","eaten","named"],"explanation":"named after the place 以地点命名。"},{"q":"7","answer":"A","options":["found","forgot","hid","sold"],"explanation":"the person who found it 发现它的人。"},{"q":"8","answer":"B","options":["garden","list","river","song"],"explanation":"a worldwide list 一份全球名录。"},{"q":"9","answer":"C","options":["money","music","nature","sport"],"explanation":"knowledge of nature 对自然的认识。"},{"q":"10","answer":"D","options":["sleeping","leaving","paying","waiting"],"explanation":"still waiting to be discovered 仍等待被发现。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'How Ants Talk', 'Ants may be small, but they are among the best (1)____ in the animal world. A single ant living alone could not survive, yet a whole colony works together almost like one (2)____. To share information, ants use chemicals that they (3)____ from their bodies. When one ant finds food, it leaves a chemical trail so that others can easily (4)____ the way back. Ants also talk by gently (5)____ each other with their feelers. Some kinds even make tiny sounds by rubbing parts of their (6)____ together. Scientists who (7)____ ants closely have learned that every signal carries a clear (8)____. A danger signal, for example, makes the whole nest react at (9)____. By studying these busy insects, researchers hope to understand more about how living things (10)____ with one another.', 132, 2, '[{"q":"1","answer":"A","options":["communicators","singers","drivers","cooks"],"explanation":"the best communicators 最善于交流者。"},{"q":"2","answer":"B","options":["price","body","season","coin"],"explanation":"like one body 像一个整体。"},{"q":"3","answer":"C","options":["buy","forget","release","sell"],"explanation":"release chemicals 释放化学物质。"},{"q":"4","answer":"D","options":["lose","forget","break","follow"],"explanation":"follow the way back 沿原路返回。"},{"q":"5","answer":"A","options":["touching","hitting","cooking","selling"],"explanation":"touching each other gently 轻轻触碰彼此。"},{"q":"6","answer":"B","options":["clocks","bodies","books","coins"],"explanation":"parts of their bodies 身体的部位。"},{"q":"7","answer":"C","options":["throw","hide","study","leave"],"explanation":"scientists who study ants 研究蚂蚁的科学家。"},{"q":"8","answer":"D","options":["price","noise","error","meaning"],"explanation":"a clear meaning 明确的含义。"},{"q":"9","answer":"A","options":["once","least","all","last"],"explanation":"react at once 立刻作出反应。"},{"q":"10","answer":"B","options":["disappear","communicate","sleep","fall"],"explanation":"communicate with one another 彼此交流。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'A Visit to a Nature Reserve', 'Last summer my family travelled to a huge nature (1)____ high on the Tibetan plateau. The air was thin and cold, but the (2)____ around us was breathtaking. Our guide explained that this protected area is (3)____ to many rare animals, including the Tibetan antelope. For years, these gentle creatures had been in (4)____, because hunters wanted their valuable wool. Thanks to the hard work of local (5)____, their numbers are slowly rising again. We were lucky enough to (6)____ a small group of them grazing in the distance. The guide warned us not to (7)____ the animals or make loud noises. He said that even a single careless visitor could (8)____ the peace of this fragile place. As I watched the antelope run freely across the (9)____, I understood why we must (10)____ such wild places for the future.', 140, 2, '[{"q":"1","answer":"C","options":["market","factory","reserve","station"],"explanation":"a nature reserve 自然保护区。"},{"q":"2","answer":"D","options":["traffic","noise","price","scenery"],"explanation":"the scenery was breathtaking 景色令人惊叹。"},{"q":"3","answer":"A","options":["home","close","late","free"],"explanation":"is home to many rare animals 是许多珍稀动物的家园。"},{"q":"4","answer":"B","options":["silence","danger","colour","order"],"explanation":"had been in danger 曾处于危险中。"},{"q":"5","answer":"C","options":["sellers","drivers","workers","cooks"],"explanation":"local workers 当地工作人员。"},{"q":"6","answer":"D","options":["sell","cook","throw","see"],"explanation":"see a small group 看到一小群。"},{"q":"7","answer":"A","options":["disturb","draw","wash","count"],"explanation":"not to disturb the animals 不要打扰动物。"},{"q":"8","answer":"B","options":["sell","destroy","build","win"],"explanation":"destroy the peace 破坏宁静。"},{"q":"9","answer":"C","options":["ceiling","market","grassland","page"],"explanation":"run across the grassland 在草原上奔跑。"},{"q":"10","answer":"D","options":["sell","forget","leave","protect"],"explanation":"protect such wild places 保护这样的野外之地。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'Life in a Coral Reef', 'Beneath the warm waters of the ocean lies one of the richest (1)____ on our planet: the coral reef. Although a reef may look like colourful rock, it is actually (2)____ by millions of tiny living animals. These reefs are (3)____ to a huge variety of fish, turtles and other sea creatures. Each animal has developed special (4)____ that help it survive in this crowded underwater world. Some fish, for example, can change colour in order to (5)____ from their enemies. Sadly, many reefs around the world are now in (6)____, because the sea is growing warmer. When the water becomes too hot, the coral slowly loses its colour and may even (7)____. Scientists are working hard to (8)____ why this is happening and how it can be stopped. They warn that if we do not (9)____ these beautiful places, future children may never get the (10)____ to see them.', 150, 2, '[{"q":"1","answer":"A","options":["habitats","markets","machines","prices"],"explanation":"the richest habitats 最丰富的栖息地。"},{"q":"2","answer":"B","options":["sold","built","eaten","lost"],"explanation":"built by millions of tiny animals 由无数小动物建成。"},{"q":"3","answer":"C","options":["late","free","home","cheap"],"explanation":"are home to a huge variety 是众多生物的家园。"},{"q":"4","answer":"D","options":["prices","songs","coins","features"],"explanation":"special features 特殊的特征。"},{"q":"5","answer":"A","options":["hide","buy","cook","drive"],"explanation":"hide from their enemies 躲避天敌。"},{"q":"6","answer":"B","options":["colour","danger","order","silence"],"explanation":"are now in danger 如今处于危险中。"},{"q":"7","answer":"C","options":["sing","dance","die","laugh"],"explanation":"may even die 甚至可能死亡。"},{"q":"8","answer":"D","options":["forget","ignore","sell","understand"],"explanation":"understand why 弄清原因。"},{"q":"9","answer":"A","options":["protect","throw","leave","break"],"explanation":"protect these beautiful places 保护这些美丽之地。"},{"q":"10","answer":"B","options":["price","chance","noise","error"],"explanation":"get the chance to see them 有机会看到它们。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U5', 'A Day at the Natural History Museum', 'On a rainy Saturday, our class visited the city''s natural (1)____ museum. As soon as we walked in, we saw the huge skeleton of a (2)____ that had lived millions of years ago. Our teacher told us that scientists had carefully (3)____ its bones from the ground, piece by piece. In the next room, glass cases were (4)____ of insects, shells and dried plants from all over the world. One display explained how a famous (5)____ called Charles Darwin had changed the way people think about life. I was most interested in a wall that showed how a single (6)____ can slowly change into many new ones over a very long (7)____. Before we left, each of us had to (8)____ down three facts that we had learned. The visit (9)____ me that there is still so much about nature we do not (10)____. I cannot wait to go back again.', 151, 2, '[{"q":"1","answer":"C","options":["garden","market","history","station"],"explanation":"natural history museum 自然历史博物馆。"},{"q":"2","answer":"D","options":["computer","building","letter","dinosaur"],"explanation":"the skeleton of a dinosaur 恐龙的骨架。"},{"q":"3","answer":"A","options":["removed","sold","eaten","sung"],"explanation":"removed its bones from the ground 把骨头从地里取出。"},{"q":"4","answer":"B","options":["late","full","free","dark"],"explanation":"were full of insects 装满了昆虫。"},{"q":"5","answer":"C","options":["singer","driver","scientist","cook"],"explanation":"a famous scientist 一位著名科学家。"},{"q":"6","answer":"D","options":["machine","price","song","species"],"explanation":"a single species 一个单一物种。"},{"q":"7","answer":"A","options":["time","coin","road","noise"],"explanation":"over a very long time 在很长时间里。"},{"q":"8","answer":"B","options":["throw","write","wash","sell"],"explanation":"write down three facts 写下三个事实。"},{"q":"9","answer":"C","options":["sold","lost","reminded","cooked"],"explanation":"reminded me that 提醒我。"},{"q":"10","answer":"D","options":["forget","hide","leave","know"],"explanation":"we do not know 我们尚不知道。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 A Trip to the Wildlife Park', '外研社版选择性必修第一册 U5 · dialogue', 3, 'Lucy: This weekend, would you like to visit the new wildlife park with me?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 Why Bees Matter', '外研社版选择性必修第一册 U5 · passage', 2, 'Bees may be small, but they are very important to nature.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 A New Kind of Frog', '外研社版选择性必修第一册 U5 · dialogue', 3, 'Host: Today we are talking to Dr Lee, who found a new kind of frog. Welcome!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 The Giant Panda', '外研社版选择性必修第一册 U5 · passage', 2, 'The giant panda is one of the best-loved animals in China.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 A Visit to the Botanical Garden', '外研社版选择性必修第一册 U5 · dialogue', 3, 'Mia: Our biology teacher wants us to visit the botanical garden. Are you coming?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 A Tip for Protecting Nature', '外研社版选择性必修第一册 U5 · passage', 2, 'Here is a simple way for anyone to help protect nature.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an Observational Journal(写一篇自然观察日记)', 'Watching a Sunflower Grow', '假设你在生物课上种了一株向日葵,并坚持记录它的生长。请用英语写一篇约90词的观察日记,内容包括:① 按时间(如第1周/第3周/第6周)记录向日葵的变化;② 至少一处用过去完成时说明''到某个时间点之前已经发生''的情况(如 By Week 6, it had already produced a flower);③ 结尾写下你的观察感受。注意语言客观、条理清楚。', 'Suppose you grew a sunflower in your biology class and kept a record of its growth. Write an observational journal (about 90 words) that: 1) records the changes week by week (e.g. Week 1 / Week 3 / Week 6); 2) uses the past perfect at least once to show what had already happened by a certain point (e.g. By Week 6, it had already produced a flower); 3) ends with how the observation made you feel.', '["按时间分段记录变化(Week 1 … / Week 3 … / Week 6 …)","用过去完成时表达''到某时间点之前已完成''(By Week 6, it had already produced a flower)","语言客观、用词准确(stem, leaves, centimetres, flower)","结尾写观察感受、句句围绕''生长''这一中心"]'::jsonb, 70, 100, 'Week 1: I planted three sunflower seeds in a pot of soft soil and placed it on the windowsill. The soil had been watered well before I added the seeds. Week 3: A thin green stem has pushed up from each seed, and the leaves are long and narrow. Week 6: The plants have grown to about thirty centimetres tall. By the time I measured them, one plant had already produced a small yellow flower. Watching nature reveal its secrets, day by day, has been truly wonderful.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The soil had been watered well before I added the seeds.","A thin green stem has pushed up from each seed.","By the time I measured them, one plant had already produced a small yellow flower.","Watching nature reveal its secrets, day by day, has been truly wonderful."]'::jsonb, '[{"wrong":"By Week 6, it produced already a flower.","correct":"By Week 6, it had already produced a flower.","note":"到某过去时间点之前已完成,用过去完成时 had done。"},{"wrong":"The leaves is long and narrow.","correct":"The leaves are long and narrow.","note":"leaves 为复数主语,系动词用 are。"},{"wrong":"I planted the seeds before I had watered the soil.","correct":"I had watered the soil before I planted the seeds.","note":"先发生的浇水动作用过去完成时,后发生的种子用一般过去时。"}]'::jsonb, '【自然观察日记结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U5', '{"title":"过去完成时 had done 速查","intro":"过去完成时表示''过去的过去'':一个动作在另一个过去动作或过去时间点之前就已经发生、完成。结构 had + 过去分词,主语无论单复数都用 had。判断口诀:看见两个过去动作,先发生的那个用 had done。","table":{"headers":["用法","标志 / 例句"],"rows":[["在过去时间点之前已完成","by + 过去时间 / before + 过去:By 1835, the finches had evolved."],["在另一个过去动作之前完成","before / after / when:After he had spent time there, he sailed on."],["间接引语回退","He said that he had studied the birds."],["no sooner…than / hardly…when 倒装","No sooner had the ship arrived than he saw the birds."]]},"specialRules":[{"rule":"一句两个过去动作,先发生的用 had done,后发生的用一般过去时","mark":"After he had collected samples, he studied them."},{"rule":"by / before / by the time + 过去,常配过去完成时","mark":"By the time we arrived, it had already left."},{"rule":"间接引语中,比''说''更早的过去动作回退为过去完成时","mark":"said (that) he had left → 原话 I left"},{"rule":"No sooner / Hardly 置于句首要倒装,助动词提前用 had","mark":"No sooner had S done … than … / Hardly had S done … when …"}],"why":["过去完成时是为了在两个过去事件之间分出先后:用 had done 标出''更早的那一个'',这样听者一下就知道哪件事先发生,不用再多解释。"],"gaokaoPoints":["看 before/after/by the time/when 等标志判断先后,先发生的填 had done;干扰项常给一般过去时或现在完成时。","间接引语回退、no sooner…than / hardly…when 句首倒装(助动词用 had)是语法填空与改错高频点。"],"examVsReal":[{"exam":"By the time I got there, the bus had left.（考试要求过去完成时）","real":"By the time I got there, the bus left.","note":"考试严格区分''过去的过去'';口语里若先后很清楚,母语者常直接用一般过去时。"},{"exam":"No sooner had he sat down than the phone rang.（考试倒装）","real":"As soon as he sat down, the phone rang.","note":"考试爱考 no sooner…than 倒装;真实表达更常用 as soon as,语序正常、更口语。"}]}'::jsonb, 'fltrp');
